#include <stdarg.h>
#include <stdint.h>
#include <stdlib.h>
#include <ucontext.h>

void __start_context(void);

/* The function's first six arguments in their registers, the rest on its
 * stack above the return address -- which is __start_context -- with the
 * stack as a call leaves it: 8 below a 16-byte boundary. */
__attribute__((weak)) void makecontext(ucontext_t *u, void (*fn)(void), int argc, ...)
{
    static const int reg[6] = { REG_RDI, REG_RSI, REG_RDX, REG_RCX, REG_R8, REG_R9 };
    uintptr_t top = (uintptr_t)u->uc_stack.ss_sp + u->uc_stack.ss_size;
    int on_stack = argc > 6 ? argc - 6 : 0;
    uintptr_t args = (top - (uintptr_t)on_stack * 8) & ~(uintptr_t)15;
    unsigned long *sp = (unsigned long *)args - 1;
    sp[0] = (unsigned long)(uintptr_t)__start_context;
    va_list ap;
    va_start(ap, argc);
    for (int i = 0; i < argc; i++) {
        long v = va_arg(ap, long);
        if (i < 6)
            u->uc_mcontext.gregs[reg[i]] = v;
        else
            sp[1 + i - 6] = (unsigned long)v;
    }
    va_end(ap);
    u->uc_mcontext.gregs[REG_RIP] = (long)(uintptr_t)fn;
    u->uc_mcontext.gregs[REG_RSP] = (long)(uintptr_t)sp;
    u->uc_mcontext.gregs[REG_RBX] = (long)(uintptr_t)u->uc_link;
    u->uc_mcontext.gregs[REG_R12] = (long)(uintptr_t)exit;
}

